?><!doctype html><html dir="<?php echo $langs->trans('DIRECTION')==='rtl'?'rtl':'ltr'; ?>"><head><meta charset="utf-8"><title><?php echo dol_escape_htmltag($operation['ref']); ?></title><style>body{font:14px/1.65 Tahoma,Arial,"Microsoft YaHei",sans-serif;color:#172033;max-width:1000px;margin:25px auto}header{border-bottom:4px solid #0d1b3e;padding:15px 0}h1{margin:5px 0}.meta,.details{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:18px 0}.box{border:1px solid #d8e0e8;padding:10px}.box small{display:block;color:#667085}.note{background:#f4f7fb;border-inline-start:4px solid #236ff5;padding:12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #d8e0e8;padding:8px;text-align:start}th{background:#f4f7fb}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()"><?php echo $langs->trans('Print'); ?></button><header><small>CHINA PLANET OPERATIONS · CONTROLLED OUTPUT</small><h1><?php echo dol_escape_htmltag($operation['title']); ?></h1><strong><?php echo dol_escape_htmltag($operation['ref']).' · '.$langs->trans('Svc_'.$operation['service_type']); ?></strong></header><div class="meta"><div class="box"><small><?php echo $langs->trans('Customer'); ?></small><?php echo dol_escape_htmltag($operation['customer_name']?:'—'); ?></div><div class="box"><small><?php echo $langs->trans('Stage'); ?></small><?php echo $langs->trans('Stage_'.$operation['stage']); ?></div><div class="box"><small><?php echo $langs->trans('Owner'); ?></small><?php echo dol_escape_htmltag($operation['owner_login']?:'—'); ?></div></div><h2><?php echo $langs->trans('ServiceDetails'); ?></h2><div class="details"><?php foreach($operation['service_data'] as $field=>$value)if($value!==''){ ?><div class="box"><small><?php echo $langs->trans('Field_'.$field); ?></small><?php echo nl2br(dol_escape_htmltag($value)); ?></div><?php } ?></div><?php if($operation['note_public']){ ?><h2><?php echo $langs->trans('CustomerVisibleNotes'); ?></h2><div class="note"><?php echo nl2br(dol_escape_htmltag($operation['note_public'])); ?></div><?php } ?><h2><?php echo $langs->trans('OperationDocuments'); ?></h2><table><tr><th><?php echo $langs->trans('DocumentType'); ?></th><th><?php echo $langs->trans('Revision'); ?></th><th><?php echo $langs->trans('Status'); ?></th></tr><?php foreach($documents as $doc)if($doc['is_current']){ ?><tr><td><?php echo dol_escape_htmltag($doc['document_type']); ?></td><td>v<?php echo (int)$doc['version_no']; ?></td><td><?php echo dol_escape_htmltag($doc['review_status']); ?></td></tr><?php } ?></table></body></html>
